<?php require 'config.php';$d=store_read();$slug=(string)($_GET['slug']??'');$post=null;foreach($d['posts'] as $p)if(($p['slug']??'')===$slug&&!empty($p['published']))$post=$p;if(!$post){http_response_code(404);$page_title='Post not found';require 'includes/header.php';echo '<section class="section wrap"><h2>Post not found</h2><a class="accent" href="blog.php">Back to blog</a></section>';require 'includes/footer.php';exit;}$page_title=t($post['title'],$post['title_bn']??$post['title']).' — HOSTNEIL';require 'includes/header.php';?><section class="section"><article class="wrap legal"><span class="eyebrow"><?= h($post['created']??'') ?></span><h1 style="font-size:3rem"><?= h(t($post['title'],$post['title_bn']??$post['title'])) ?></h1><p><?= h(t($post['excerpt'],$post['excerpt_bn']??$post['excerpt'])) ?></p><div style="white-space:pre-wrap;line-height:1.95;color:#c4cfde"><?= h(t($post['body'],$post['body_bn']??$post['body'])) ?></div><p style="margin-top:30px"><a class="accent" href="blog.php">← <?= t('Back to blog','ব্লগে ফিরুন') ?></a></p></article></section><?php require 'includes/footer.php'; ?>